from __future__ import absolute_import
import logging
from collections import defaultdict
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.pages.panels.navigation import NavigationPanel
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.panels.details import DetailPanel
from taf.selenium.sbts_fsm3.pages.configuration.configuration_management import ConfigurationCommonAction
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class HardwareErrorsPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Hardware Errors will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Hardware Errors']

    def __init__(self, driver):
        super(HardwareErrorsPage, self).__init__(driver)
        self._navigation_panel = HardwareErrorsPageNavigationPanel(driver)
        self._view_panel = HardwareErrorsPageViewPanel(driver)
        self._detail_panel = HardwareErrorsPageDetailPanel(driver)
        self.common_actions = {
            'load_commissioning_file_and_check_load_status':
                self._view_panel.load_commissioning_file_and_check_load_status,
            'validate_plan': self._view_panel.validate_plan,
            'activate_plan': self._view_panel.activate_plan,
        }
        self.__dict__.update(self.common_actions)

    def get_hardware_errors(self, timeout):
        return self._view_panel.get_hardware_errors(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class HardwareErrorsPageNavigationPanel(NavigationPanel):
    pass


class HardwareErrorsPageViewPanel(ViewPanel):
    _ERROR_TABLE_ROWS_XPATH = '//parameter-validation-errors//tbody/tr'
    _OBJECT_NAME_XPATH = '/td[contains(@class,"object-name")]//highlighter/span'
    _ERROR_DESCRIPTION_XPATH = '//pdl-feedback/span'

    def __init__(self, driver):
        super(HardwareErrorsPageViewPanel, self).__init__(driver)
        common_action = ConfigurationCommonAction(driver)
        self.common_actions = {
            'load_commissioning_file_and_check_load_status':
                common_action.load_commissioning_file_and_check_load_status,
            'validate_plan': common_action.validate_plan,
            'activate_plan': common_action.activate_plan,
        }
        self.__dict__.update(self.common_actions)

    def get_hardware_errors(self, timeout):
        try:
            hardware_errors = defaultdict(list)
            error_row_xpath_list = self.get_elements_xpath_list(self._ERROR_TABLE_ROWS_XPATH, timeout)
            for error_row_xpath in error_row_xpath_list:
                error_row_key = self._get_object_name(error_row_xpath, timeout)
                error_row_value = self._get_error_description(error_row_xpath, timeout)
                hardware_errors[error_row_key].append(error_row_value)
            return hardware_errors
        except TimeoutException:
            logging.warning('No hardware errors exist, empty dict will be returned.')
            return {}

    def _get_object_name(self, row_base_xpath, timeout):
        row_object_name_xpath = row_base_xpath + self._OBJECT_NAME_XPATH
        return self.get_text_by_xpath(row_object_name_xpath, timeout)

    def _get_error_description(self, row_base_xpath, timeout):
        row_error_description = ''
        row_error_description_base_xpath = row_base_xpath + self._ERROR_DESCRIPTION_XPATH
        row_error_description_xpath_list = self.get_elements_xpath_list(row_error_description_base_xpath, timeout)

        for xpath in row_error_description_xpath_list:
            row_error_description = ' '.join([row_error_description, self.get_text_by_xpath(xpath, timeout)])
        return row_error_description.strip()


class HardwareErrorsPageDetailPanel(DetailPanel):
    pass
